export type TechIconKey = keyof typeof RAW_TECH_ICONS

const dataUriCache = new Map<TechIconKey, string>()
let warmupStarted = false

/**
 * Returns a memoized UTF-8 SVG data URI for an icon key with zero network requests.
 */
export function getTechIconUrl(key: TechIconKey): string {
    const cached = dataUriCache.get(key)
    if (cached) return cached
    const uri = 'data:image/svg+xml;utf8,' + encodeURIComponent(RAW_TECH_ICONS[key])
    dataUriCache.set(key, uri)
    return uri
}

/**
 * Pre-decodes all bundled icon data URIs into browser memory during idle frames
 * so popups, hover states, and robot spawns paint without decode jitter.
 */
export function warmupTechIcons(): void {
    if (warmupStarted || typeof window === 'undefined') return
    warmupStarted = true

    const runWarmup = () => {
        const keys = Object.keys(RAW_TECH_ICONS) as TechIconKey[]
        for (let i = 0; i < keys.length; i++) {
            const img = new Image()
            img.decoding = 'async'
            img.src = getTechIconUrl(keys[i])
        }
    }

    if ('requestIdleCallback' in window) {
        ;(window as Window & { requestIdleCallback: (cb: () => void, opts?: { timeout: number }) => number }).requestIdleCallback(
            runWarmup,
            { timeout: 1200 }
        )
    } else {
        setTimeout(runWarmup, 250)
    }
}
